async function ensureNotifPermission(){let p=nativeNotifPlugin();if(!p||!nativePlatform())return false;try{let r=await p.checkPermissions();if(r.display!=="granted")r=await p.requestPermissions();return r.display==="granted"}catch(e){console.warn("Permissão de notificação",e);return false}}
async function cancelHabitNotifications(hid){let p=nativeNotifPlugin();if(!p||!nativePlatform())return;try{await p.cancel({notifications:habitNotifIds(hid).map(id=>({id}))})}catch(e){console.warn("Cancelamento de lembretes",e)}}
async function syncHabitNotifications(h,showMessage=false){let p=nativeNotifPlugin();if(!p||!nativePlatform()){if(showMessage&&h.reminder?.enabled)toast("Lembretes salvos. Eles serão ativados quando este backup for usado no APK Android.","info","Lembretes Android");return false}try{await cancelHabitNotifications(h.id);if(!h.reminder?.enabled)return true;let times=reminderTimes(h);if(!times.length)return false;if(!await ensureNotifPermission()){if(showMessage)toast("Permita notificações do Smart Life nas configurações do Android.","warn","Permissão necessária");return false}let ids=habitNotifIds(h.id),notifications=times.map((time,i)=>{let [hour,minute]=time.split(":").map(Number);return{id:ids[i],title:`Smart Life • ${h.title}`,body:`Hora de ${h.title}. Abra o Smart Life e marque quando concluir.`,smallIcon:NOTIF_SMALL_ICON,iconColor:NOTIF_ICON_COLOR,actionTypeId:"HABIT_ACTIONS",schedule:{on:{hour,minute},allowWhileIdle:true},extra:{habitId:h.id,nav:"habits"}}});await p.schedule({notifications});if(showMessage)toast(`${notifications.length} horário(s) de lembrete programado(s).`,"success","Notificações ativadas");return true}catch(e){console.error(e);if(showMessage)toast("Não foi possível programar as notificações neste aparelho.","error","Falha nas notificações");return false}}
async function testHabitNotification(title="Hábito"){let p=nativeNotifPlugin();if(!p||!nativePlatform())return toast("O teste de notificação funciona no APK Android. No computador, a configuração é apenas salva no backup.","info","Teste no Android");if(!await ensureNotifPermission())return toast("Permita notificações do Smart Life no Android.","warn","Permissão necessária");try{await p.schedule({notifications:[{id:notifHash(`test:${Date.now()}`),title:`Smart Life • ${title||"Hábito"}`,body:"Notificação de teste. Seus lembretes estão funcionando.",smallIcon:NOTIF_SMALL_ICON,iconColor:NOTIF_ICON_COLOR,schedule:{at:new Date(Date.now()+1800)},extra:{nav:"habits"}}]});toast("A notificação de teste deve aparecer em instantes.","success","Teste enviado")}catch(e){toast("Não foi possível enviar a notificação de teste.","error")}}
async function syncAllHabitNotifications(){if(!nativePlatform())return;for(const h of D.habits)await syncHabitNotifications(h,false)}
async function initNativeNotifications(){let p=nativeNotifPlugin();if(!p||!nativePlatform())return;try{await p.addListener?.("localNotificationActionPerformed",()=>{nav="habits";render();scrollTo(0,0)});setTimeout(syncAllHabitNotifications,800)}catch(e){console.warn("Inicialização de notificações",e)}}
async function requestInitialNotificationPermission(){let p=nativeNotifPlugin();if(!p||!nativePlatform()||!D.onboarded)return false;let key=`smartlife-notification-requested:${currentAccount?.id||"local"}`;try{let status=await p.checkPermissions();if(status.display==="granted"){localStorage.setItem(key,"1");setTimeout(()=>{syncAllHabitNotifications();scheduleDailySummary()},300);return true}if(localStorage.getItem(key)==="1")return false;status=await p.requestPermissions();localStorage.setItem(key,"1");if(status.display==="granted"){setTimeout(()=>{syncAllHabitNotifications();scheduleDailySummary()},300);return true}return false}catch(e){console.warn("Solicitação inicial de notificações",e);return false}}
function xpForDate(date=iso()){let earned=D.history.filter(x=>x.date===date&&x.type==="xp").reduce((s,x)=>s+Number(x.amount||0),0),reverted=D.history.filter(x=>x.date===date&&x.type==="habit_undo").reduce((s,x)=>s+Number(x.amount||0),0);return Math.max(0,earned-reverted)}function todayXP(){return xpForDate(iso())}function need(l=D.level){return 500+(l-1)*250}function levelCalc(){let x=D.totalXP,l=1;while(x>=need(l)){x-=need(l);l++}return{l,x,n:need(l)}}function rank(){let l=D.level;return l>=50?["S","Soberano"]:l>=35?["A","Elite"]:l>=25?["B","Veterano"]:l>=15?["C","Experiente"]:l>=8?["D","Promissor"]:["E","Caçador Fraco"]}
