function evaluateTitles(show=true){
 let m=titleMetrics(),newly=[];D.titles.forEach(t=>{let rule=titleRule(t.name,m);if(rule.test&&!t.unlocked){t.unlocked=true;newly.push(t)}});
 if(newly.length){let chosen=newly[newly.length-1];D.titles.forEach(t=>t.equipped=t.id===chosen.id);newly.forEach(t=>hist("title_unlock",{title:t.name}));if(show)newly.forEach(t=>toast(`Você cumpriu: ${titleRule(t.name,m).desc} ${t.id===chosen.id?"Título equipado automaticamente.":""}`.trim(),"success",`🏆 ${t.name} conquistado!`));}
 return newly
}
