const GEMINI_MODEL="gemini-3.5-flash-lite";
function aiDefaults(){return{provider:"gemini",apiKey:"",autoOnline:false,lastSync:"",lastTest:"",permissions:{profile:true,missions:true,habits:true,projects:true,finance:false}}}
function aiConfig(){let raw=D.settings?.ai||{},base=aiDefaults();return Object.assign(base,raw,{permissions:Object.assign(base.permissions,raw.permissions||{})})}
function aiSave(fields={}){let current=aiConfig(),next=Object.assign(current,fields||{});if(fields.permissions)next.permissions=Object.assign(current.permissions,fields.permissions);D.settings.ai=next;save()}
