 if(p.profile){let attrs=ATTR.map(a=>`${a[1]}: ${Number(D.attrs?.[a[0]]||0)}`).join(", ");lines.push(`Perfil: ${D.profile.name}; nível ${D.level}; título ${(D.titles.find(t=>t.equipped)||{}).name||"sem título"}; atributos ${attrs}`);if(answers.length)lines.push(`Preferências do primeiro acesso: ${JSON.stringify(answers)}`)}
