 if(p.projects){let projects=D.projects.filter(x=>!x.done).slice(0,10).map(x=>`${x.title}${x.due?` (prazo ${x.due})`:""} • ${Math.round(projectPct(x))}%`);lines.push(`Projetos ativos: ${projects.join("; ")||"nenhum"}`)}
