function financeLoanToggleInstallment(installmentId,loanId){let i=D.finance.loan_installments.find(x=>Number(x.id)===Number(installmentId));if(!i)return;let paid=String(i.status)==="paid"||!!i.paid_date;i.status=paid?"pending":"paid";i.paid_date=paid?null:iso();save();toast(paid?"Parcela reaberta.":"Parcela marcada como paga.","success","Empréstimo atualizado");financeLoanInstallmentsModal(loanId)}
function financeRecurring(){let o=financeOwnerId(),ex=D.finance.recurring_expenses.filter(x=>financeOwn(x,o)).sort((a,b)=>Number(b.active)-Number(a.active)||String(a.description).localeCompare(String(b.description),"pt-BR")),inc=D.finance.recurring_incomes.filter(x=>financeOwn(x,o)).sort((a,b)=>Number(b.active)-Number(a.active)||String(a.description).localeCompare(String(b.description),"pt-BR")),activeEx=ex.filter(x=>Number(x.active)!==0&&financeRecurrenceActiveForMonth(x,financeMonthSelected)),activeInc=inc.filter(x=>Number(x.active)!==0&&financeRecurrenceActiveForMonth(x,financeMonthSelected)),monthlyEx=activeEx.reduce((s,x)=>s+Number(x.amount||0),0),monthlyInc=activeInc.reduce((s,x)=>s+Number(x.amount||0),0);return `<div class="financeRecurringHeader"><div><h2>Recorrentes</h2><p class="sub">Controle regras mensais sem misturar todos os lançamentos na mesma tela.</p></div><div class="row"><button class="pill" data-fin-rec-new="expense">＋ Despesa recorrente</button><button class="pill" data-fin-rec-new="income">＋ Receita recorrente</button></div></div><div class="recurringSummary"><div><span>Despesas ativas no mês</span><b class="warnText">${moneyBR(monthlyEx)}</b><small>${activeEx.length} regra(s)</small></div><div><span>Receitas ativas no mês</span><b class="positive">${moneyBR(monthlyInc)}</b><small>${activeInc.length} regra(s)</small></div><div><span>Impacto recorrente</span><b class="${monthlyInc-monthlyEx>=0?"positive":"negative"}">${moneyBR(monthlyInc-monthlyEx)}</b><small>${esc(financeMonthLabel(financeMonthSelected))}</small></div></div><div class="grid2"><div class="card"><div class="sectionMini"><h2>Despesas recorrentes</h2><span class="financeCount">${ex.length}</span></div><div class="list">${ex.map(x=>`<div class="financeRecurringItem ${Number(x.active)===0?"inactive":""}"><div class="grow"><b>${esc(x.description)}</b><small>Dia ${x.due_day} • ${moneyBR(x.amount)} • ${esc(financeCatName(x.category_id))}</small><span class="recurrenceState">${Number(x.active)!==0?"Ativa":"Pausada"} • desde ${esc(String(x.start_month||"").slice(0,7)||"sem início")}${x.end_month?` • até ${esc(x.end_month)}`:" • sem data final"}</span></div><button class="pill" data-fin-rec-edit="expense:${x.id}">Editar</button><button class="iconAction" data-fin-rec-toggle="expense:${x.id}" title="${Number(x.active)!==0?"Pausar":"Ativar"}">${Number(x.active)!==0?"Ⅱ":"▶"}</button><button class="iconAction danger" data-fin-rec-del="expense:${x.id}" title="Excluir recorrência">×</button></div>`).join("")||`<p class="sub">Nenhuma.</p>`}</div></div><div class="card"><div class="sectionMini"><h2>Receitas recorrentes</h2><span class="financeCount">${inc.length}</span></div><div class="list">${inc.map(x=>`<div class="financeRecurringItem ${Number(x.active)===0?"inactive":""}"><div class="grow"><b>${esc(x.description)}</b><small>Dia ${x.expected_day} • ${moneyBR(x.amount)} • ${esc(financeCatName(x.category_id))}</small><span class="recurrenceState">${Number(x.active)!==0?"Ativa":"Pausada"} • desde ${esc(String(x.start_month||"").slice(0,7)||"sem início")}${x.end_month?` • até ${esc(x.end_month)}`:" • sem data final"}</span></div><button class="pill" data-fin-rec-edit="income:${x.id}">Editar</button><button class="iconAction" data-fin-rec-toggle="income:${x.id}" title="${Number(x.active)!==0?"Pausar":"Ativar"}">${Number(x.active)!==0?"Ⅱ":"▶"}</button><button class="iconAction danger" data-fin-rec-del="income:${x.id}" title="Excluir recorrência">×</button></div>`).join("")||`<p class="sub">Nenhuma.</p>`}</div></div></div>`}
function financeRecurringModal(kind,obj){let o=financeOwnerId(),isExpense=kind==="expense",arr=isExpense?D.finance.recurring_expenses:D.finance.recurring_incomes,cats=D.finance.categories.filter(c=>financeOwn(c,o)&&c.kind===(isExpense?"expense":"income")),x=obj||{id:nextFinanceId(arr),owner_id:o,description:"",amount:0,[isExpense?"due_day":"expected_day"]:10,category_id:null,start_month:financeMonthSelected,end_month:null,active:1};modal(`<div class="mh"><div><h2>${obj?"Editar":"Nova"} ${isExpense?"despesa":"receita"} recorrente</h2><p class="sub">A regra será usada nos meses futuros sem encher a tela atual.</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Descrição</label><input id="frDesc" class="field" value="${esc(x.description||"")}"><label>Valor</label><input id="frAmount" class="field" type="number" step="0.01" min="0" value="${Number(x.amount||0)}"><div class="formGrid2"><div><label>Dia do mês</label><input id="frDay" class="field" type="number" min="1" max="31" value="${Number(isExpense?x.due_day:x.expected_day)||10}"></div><div><label>Categoria</label><select id="frCat" class="field"><option value="">Sem categoria</option>${cats.map(c=>`<option value="${c.id}" ${Number(c.id)===Number(x.category_id)?"selected":""}>${esc(c.name)}</option>`).join("")}</select></div></div><div class="formGrid2"><div><label>Começa em</label><input id="frStart" class="field" type="month" value="${String(x.start_month||financeMonthSelected).slice(0,7)}"></div><div><label>Final opcional</label><input id="frEnd" class="field" type="month" value="${String(x.end_month||"").slice(0,7)}"></div></div>${isExpense?`<label>Estabelecimento</label><input id="frExtra" class="field" value="${esc(x.merchant||"")}" placeholder="Opcional">`:`<label>Observação</label><input id="frExtra" class="field" value="${esc(x.notes||"")}" placeholder="Opcional">`}<label class="toggle-line"><input id="frActive" type="checkbox" ${Number(x.active)!==0?"checked":""}> Recorrência ativa</label><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="frSave">Salvar recorrência</button></div></div>`);byId("frSave").onclick=()=>{let y={...x,description:byId("frDesc").value.trim(),amount:Number(byId("frAmount").value||0),category_id:Number(byId("frCat").value)||null,start_month:byId("frStart").value||financeMonthSelected,end_month:byId("frEnd").value||null,active:byId("frActive").checked?1:0};y[isExpense?"due_day":"expected_day"]=Math.max(1,Math.min(31,Number(byId("frDay").value)||10));if(isExpense){y.merchant=byId("frExtra").value.trim();y.payment_method=y.payment_method||"pix"}else y.notes=byId("frExtra").value.trim();if(!y.description||y.amount<=0)return toast("Informe descrição e valor da recorrência.","warn","Dados incompletos");let i=arr.findIndex(v=>Number(v.id)===Number(y.id));i>=0?arr[i]=y:arr.push(y);let from=financeMonthSelected;if(isExpense){D.finance.expenses.forEach(e=>{if(Number(e.recurrence_id)!==Number(y.id)||financeRecordMonth(e,"expense")<from||String(e.status)==="paid"||e.paid_date)return;let m=financeRecordMonth(e,"expense");e.description=y.description;e.amount=y.amount;e.category_id=y.category_id;e.merchant=y.merchant||"";e.due_date=financeDateForMonthDay(m,y.due_day);e.purchase_date=e.purchase_date||e.due_date})}else{D.finance.incomes.forEach(e=>{if(Number(e.recurrence_id)!==Number(y.id)||financeRecordMonth(e,"income")<from||String(e.status)==="received"||e.received_date)return;let m=financeRecordMonth(e,"income");e.description=y.description;e.amount_expected=y.amount;e.category_id=y.category_id;e.notes=y.notes||"";e.expected_date=financeDateForMonthDay(m,y.expected_day)})}if(y.active)ensureFinanceRecurringForMonth(financeMonthSelected);save();closeM();render();toast("Regra recorrente atualizada. Os próximos lançamentos usarão os novos dados.","success","Recorrência salva")}}
function financeRecurringToggle(kind,id){let arr=kind==="expense"?D.finance.recurring_expenses:D.finance.recurring_incomes,x=arr.find(v=>Number(v.id)===Number(id));if(!x)return;x.active=Number(x.active)===0?1:0;if(x.active)ensureFinanceRecurringForMonth(financeMonthSelected);save();render();toast(x.active?"Recorrência ativada.":"Recorrência pausada.","info","Recorrentes")}
function financeRecurringDeleteModal(kind,id){let isExpense=kind==="expense",arr=isExpense?D.finance.recurring_expenses:D.finance.recurring_incomes,x=arr.find(v=>Number(v.id)===Number(id));if(!x)return;modal(`<div class="mh"><div><h2>Excluir recorrência?</h2><p class="sub">${esc(x.description)} • ${moneyBR(x.amount)}</p></div><button class="x" id="cx">×</button></div><div class="dangerBox"><b>Escolha o que fazer com os lançamentos já gerados</b><p>Você pode apagar apenas a regra recorrente e manter os lançamentos existentes, ou também remover os lançamentos futuros ainda pendentes.</p></div><div class="recurringDeleteOptions"><button class="pill" id="recKeep">Excluir regra e manter lançamentos</button><button class="btn red" id="recFuture">Excluir regra + futuros pendentes</button></div><div class="modalActions"><button class="pill" data-close>Cancelar</button></div>`);let removeRule=()=>{if(isExpense)D.finance.recurring_expenses=D.finance.recurring_expenses.filter(v=>Number(v.id)!==Number(id));else D.finance.recurring_incomes=D.finance.recurring_incomes.filter(v=>Number(v.id)!==Number(id))};byId("recKeep").onclick=()=>{removeRule();save();closeM();render();toast("A regra foi excluída; lançamentos existentes foram mantidos.","info","Recorrência excluída")};byId("recFuture").onclick=()=>{let month=financeMonthSelected;if(isExpense)D.finance.expenses=D.finance.expenses.filter(e=>!(Number(e.recurrence_id)===Number(id)&&financeRecordMonth(e,"expense")>=month&&String(e.status)!=="paid"&&!e.paid_date));else D.finance.incomes=D.finance.incomes.filter(e=>!(Number(e.recurrence_id)===Number(id)&&financeRecordMonth(e,"income")>=month&&String(e.status)!=="received"&&!e.received_date));removeRule();save();closeM();render();toast("Regra e lançamentos futuros pendentes foram removidos.","info","Recorrência excluída")}}

function financePlanning(){let o=financeOwnerId(),months=[0,1,2].map(n=>financeShiftMonth(financeMonthSelected,n)),cats=D.finance.categories.filter(c=>financeOwn(c,o)&&c.kind==="expense"),budgets=D.finance.budgets.filter(x=>financeOwn(x,o)&&String(x.month)===financeMonthSelected);return `<div class="financeToolbar"><div><h2>Planejamento</h2><p class="sub">Previsão dos próximos meses e orçamento por categoria.</p></div><button class="btn" data-fin-budget-new>＋ Novo orçamento</button></div><div class="financeForecast">${months.map(m=>{ensureFinanceRecurringForMonth(m);let s=financeSummary(m),inst=D.finance.loan_installments.filter(i=>financeOwn(i,o)&&String(i.due_date||"").slice(0,7)===m&&String(i.status)!=="paid").reduce((a,i)=>a+Number(i.amount||0),0);return`<div class="card forecastCard"><b>${esc(financeMonthLabel(m))}</b><span>Receitas <strong class="positive">${moneyBR(s.expected)}</strong></span><span>Despesas <strong>${moneyBR(s.totalExp)}</strong></span><span>Parcelas <strong>${moneyBR(inst)}</strong></span><span>Saldo previsto <strong class="${s.expected-s.totalExp-inst>=0?"positive":"negative"}">${moneyBR(s.expected-s.totalExp-inst)}</strong></span></div>`}).join("")}</div><div class="card" style="margin-top:14px"><div class="sectionMini"><div><h2>Orçamento por categoria</h2><p class="sub">${esc(financeMonthLabel(financeMonthSelected))}</p></div></div><div class="budgetList">${budgets.length?budgets.map(b=>{let spent=D.finance.expenses.filter(e=>financeOwn(e,o)&&financeRecordMonth(e,"expense")===financeMonthSelected&&Number(e.category_id)===Number(b.category_id)).reduce((s,e)=>s+Number(e.amount||0),0),pct=Number(b.limit_amount)?spent/Number(b.limit_amount)*100:0;return`<div class="budgetRow"><div class="grow"><b>${esc(financeCatName(b.category_id))}</b><small>${moneyBR(spent)} de ${moneyBR(b.limit_amount)}</small><div class="bar"><i style="width:${Math.min(100,pct)}%"></i></div></div><strong class="${pct>100?"negative":""}">${pct.toFixed(0)}%</strong><button class="iconAction danger" data-fin-budget-del="${b.id}" title="Remover">×</button></div>`}).join(""):`<p class="sub">Nenhum orçamento definido para este mês.</p>`}</div></div>`}
function financeBudgetModal(){let o=financeOwnerId(),cats=D.finance.categories.filter(c=>financeOwn(c,o)&&c.kind==="expense");modal(`<div class="mh"><div><h2>Novo orçamento</h2><p class="sub">Defina um limite por categoria para ${esc(financeMonthLabel(financeMonthSelected))}.</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Categoria</label><select id="fbCat" class="field"><option value="">Selecione</option>${cats.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join("")}</select><label>Limite mensal</label><input id="fbLimit" class="field" type="number" min="0" step="0.01"><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="fbSave">Salvar orçamento</button></div></div>`);byId("fbSave").onclick=()=>{let category_id=Number(byId("fbCat").value),limit_amount=Number(byId("fbLimit").value||0);if(!category_id||limit_amount<=0)return toast("Selecione uma categoria e informe o limite.","warn");let old=D.finance.budgets.find(b=>financeOwn(b,o)&&String(b.month)===financeMonthSelected&&Number(b.category_id)===category_id);if(old)old.limit_amount=limit_amount;else D.finance.budgets.push({id:nextFinanceId(D.finance.budgets),owner_id:o,month:financeMonthSelected,category_id,limit_amount,created_at:new Date().toISOString()});save();closeM();render();toast("Orçamento salvo para o mês.","success","Planejamento atualizado")}}
function financeEditModal(kind,obj){let o=financeOwnerId(),cats=D.finance.categories.filter(c=>financeOwn(c,o)&&c.kind===(kind==="income"?"income":"expense")),cards=D.finance.cards.filter(c=>financeOwn(c,o));if(kind==="expense"){let x=obj||{id:nextFinanceId(D.finance.expenses),owner_id:o,description:"",amount:0,purchase_date:financeDateForMonthDay(financeMonthSelected,new Date().getDate()),due_date:financeDateForMonthDay(financeMonthSelected,10),status:"pending",payment_method:"pix",expense_type:"variable",billing_month:financeMonthSelected,list_month:financeMonthSelected,created_at:new Date().toISOString()};modal(`<div class="mh"><div><h2>${obj?"Editar":"Nova"} despesa</h2><p class="sub">Lançamento de ${esc(financeMonthLabel(financeMonthSelected))}.</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Descrição</label><input id="fdDesc" class="field" value="${esc(x.description)}"><label>Valor</label><input id="fdAmount" class="field" type="number" step="0.01" min="0" value="${Number(x.amount||0)}"><div class="formGrid2"><div><label>Vencimento</label><input id="fdDate" class="field" type="date" value="${String(x.due_date||financeDateForMonthDay(financeMonthSelected,10)).slice(0,10)}"></div><div><label>Status</label><select id="fdStatus" class="field"><option value="pending" ${String(x.status)!=="paid"?"selected":""}>Pendente</option><option value="paid" ${String(x.status)==="paid"?"selected":""}>Paga</option></select></div></div><label>Categoria</label><select id="fdCat" class="field"><option value="">Sem categoria</option>${cats.map(c=>`<option value="${c.id}" ${Number(c.id)===Number(x.category_id)?"selected":""}>${esc(c.name)}</option>`).join("")}</select><label>Cartão</label><select id="fdCard" class="field"><option value="">Sem cartão</option>${cards.map(c=>`<option value="${c.id}" ${Number(c.id)===Number(x.card_id)?"selected":""}>${esc(c.name)}</option>`).join("")}</select>${x.recurrence_id?`<div class="recurrenceHint">↻ Esta é uma ocorrência recorrente. Para alterar os próximos meses, use a aba <b>Recorrentes</b>.</div>`:""}<div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="finSave">Salvar despesa</button></div></div>`);byId("finSave").onclick=()=>{let y={...x,description:byId("fdDesc").value.trim(),amount:Number(byId("fdAmount").value||0),due_date:byId("fdDate").value,purchase_date:x.purchase_date||iso(),status:byId("fdStatus").value,paid_date:byId("fdStatus").value==="paid"?(x.paid_date||iso()):null,category_id:Number(byId("fdCat").value)||null,card_id:Number(byId("fdCard").value)||null,billing_month:byId("fdDate").value.slice(0,7),list_month:byId("fdDate").value.slice(0,7)};if(!y.description||y.amount<=0)return toast("Informe descrição e valor da despesa.","warn","Dados incompletos");let duplicate=D.finance.expenses.find(v=>Number(v.id)!==Number(y.id)&&financeOwn(v,o)&&String(v.description||"").trim().toLocaleLowerCase("pt-BR")===y.description.toLocaleLowerCase("pt-BR")&&Number(v.amount)===Number(y.amount)&&String(v.due_date||"").slice(0,10)===String(y.due_date).slice(0,10));let persist=()=>{let i=D.finance.expenses.findIndex(v=>Number(v.id)===Number(y.id));i>=0?D.finance.expenses[i]=y:D.finance.expenses.push(y);save();closeM();render();toast("Despesa salva no módulo financeiro.","success","Finanças atualizadas")};if(duplicate)return confirmDialog({title:"Possível despesa duplicada",message:`Já existe “${duplicate.description}” com o mesmo valor e vencimento.`,description:"Salve somente se este lançamento realmente for diferente.",confirmText:"Salvar mesmo assim",onConfirm:persist});persist()};return}
if(kind==="income"){let x=obj||{id:nextFinanceId(D.finance.incomes),owner_id:o,description:"",amount_expected:0,amount_received:0,expected_date:financeDateForMonthDay(financeMonthSelected,1),status:"pending",created_at:new Date().toISOString()};modal(`<div class="mh"><div><h2>${obj?"Editar":"Nova"} receita</h2><p class="sub">Receita de ${esc(financeMonthLabel(financeMonthSelected))}.</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Descrição</label><input id="fiDesc" class="field" value="${esc(x.description)}"><label>Valor previsto</label><input id="fiExpected" class="field" type="number" step="0.01" min="0" value="${Number(x.amount_expected||0)}"><label>Valor recebido</label><input id="fiReceived" class="field" type="number" step="0.01" min="0" value="${Number(x.amount_received||0)}"><label>Data prevista</label><input id="fiDate" class="field" type="date" value="${String(x.expected_date||financeDateForMonthDay(financeMonthSelected,1)).slice(0,10)}"><label>Status</label><select id="fiStatus" class="field"><option value="pending" ${String(x.status)!=="received"?"selected":""}>Pendente</option><option value="received" ${String(x.status)==="received"?"selected":""}>Recebida</option></select>${x.recurrence_id?`<div class="recurrenceHint">↻ Esta é uma ocorrência recorrente. Para alterar os próximos meses, use a aba <b>Recorrentes</b>.</div>`:""}<div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="finSave">Salvar receita</button></div></div>`);byId("finSave").onclick=()=>{let y={...x,description:byId("fiDesc").value.trim(),amount_expected:Number(byId("fiExpected").value||0),amount_received:Number(byId("fiReceived").value||0),expected_date:byId("fiDate").value,status:byId("fiStatus").value,received_date:byId("fiStatus").value==="received"?(x.received_date||iso()):null};if(!y.description||y.amount_expected<=0)return toast("Informe descrição e valor da receita.","warn","Dados incompletos");if(y.status==="received"&&!y.amount_received)y.amount_received=y.amount_expected;let i=D.finance.incomes.findIndex(v=>Number(v.id)===Number(y.id));i>=0?D.finance.incomes[i]=y:D.finance.incomes.push(y);save();closeM();render();toast("Receita salva no módulo financeiro.","success","Finanças atualizadas")};return}
if(kind==="card"){let x=obj||{id:nextFinanceId(D.finance.cards),owner_id:o,name:"",bank:"",brand:"",credit_limit:0,closing_day:1,due_day:10,color:"#22c55e",is_active:1};modal(`<div class="mh"><div><h2>${obj?"Editar":"Novo"} cartão</h2></div><button class="x" id="cx">×</button></div><div class="form"><label>Nome</label><input id="fcName" class="field" value="${esc(x.name)}"><label>Banco</label><input id="fcBank" class="field" value="${esc(x.bank||"")}"><label>Bandeira</label><input id="fcBrand" class="field" value="${esc(x.brand||"")}"><label>Limite</label><input id="fcLimit" class="field" type="number" step="0.01" value="${Number(x.credit_limit||0)}"><div class="formGrid2"><div><label>Fechamento</label><input id="fcClose" class="field" type="number" min="1" max="31" value="${x.closing_day||1}"></div><div><label>Vencimento</label><input id="fcDue" class="field" type="number" min="1" max="31" value="${x.due_day||10}"></div></div><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="finSave">Salvar cartão</button></div></div>`);byId("finSave").onclick=()=>{let y={...x,name:byId("fcName").value.trim(),bank:byId("fcBank").value.trim(),brand:byId("fcBrand").value.trim(),credit_limit:Number(byId("fcLimit").value||0),closing_day:Number(byId("fcClose").value||1),due_day:Number(byId("fcDue").value||10)};if(!y.name)return toast("Informe o nome do cartão.","warn");let i=D.finance.cards.findIndex(v=>Number(v.id)===Number(y.id));i>=0?D.finance.cards[i]=y:D.finance.cards.push(y);save();closeM();render();toast("Cartão salvo.","success","Finanças atualizadas")};return}}
function nextFinanceId(arr){return Math.max(0,...arr.map(x=>Number(x.id)||0))+1}
function financeDelete(kind,id){let map={income:["receita","incomes"],expense:["despesa","expenses"]},m=map[kind];if(!m)return;let item=D.finance[m[1]].find(x=>Number(x.id)===Number(id));confirmDialog({title:`Mover ${m[0]} para a lixeira?`,message:`A ${m[0]} poderá ser restaurada por 30 dias.`,description:"A regra recorrente continuará existindo até ser removida na aba Recorrentes.",danger:true,confirmText:"Mover para lixeira",onConfirm:()=>{moveToTrash(kind,item);D.finance[m[1]]=D.finance[m[1]].filter(x=>Number(x.id)!==Number(id));save();render();toast(`${m[0][0].toUpperCase()+m[0].slice(1)} movida para a lixeira.`,"info","Lixeira")}})}
function exportFinance(){let data=normalizeFinance(D.finance),blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),a=document.createElement("a"),url=URL.createObjectURL(blob);a.href=url;a.download=`smart-life-finance-${iso()}.smartlife-finance.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Arquivo financeiro compatível com computador e APK gerado.","success","Finanças exportadas")}
function importFinance(){let f=document.createElement("input");f.type="file";f.accept=".json,.smartlife-finance,application/json";f.onchange=()=>{let file=f.files?.[0];if(!file)return;let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(x?.format!=="smart-life-finance"||!Array.isArray(x.expenses)||!Array.isArray(x.incomes))throw new Error();D.finance=normalizeFinance(x);localStorage.removeItem("smartlifeSkipFinanceSeed");ensureFinanceRecurringForMonth(financeMonthSelected);save();render();toast("Dados do Smart Finance importados com sucesso.","success","Finanças restauradas")}catch{toast("Use um arquivo .smartlife-finance.json válido.","error","Arquivo financeiro inválido")}};r.readAsText(file)};f.click()}

