function reviewOnboardingModal(){let old=Array.isArray(D.onboardingProfile?.answers)?D.onboardingProfile.answers:[];modal(`<div class="mh"><div><span class="kicker">RECALIBRAR O SISTEMA</span><h2>Atualizar objetivos iniciais</h2><p class="sub">Isso altera somente as próximas sugestões e o Smart Daily. Seu XP, hábitos e histórico serão preservados.</p></div><button class="x" id="cx">×</button></div><div class="goalReviewList">${ONBOARDING_QUESTIONS.map((q,qi)=>`<fieldset class="goalReviewQuestion" data-goal-question="${qi}" data-multi="${q[2]?1:0}"><legend>${qi+1}. ${esc(q[0])}</legend>${q[1].map((o,oi)=>{let checked=q[2]?Array.isArray(old[qi])&&old[qi].includes(oi):Number(old[qi])===oi;return`<label><input type="${q[2]?"checkbox":"radio"}" name="goal-${qi}" value="${oi}" ${checked?"checked":""}><span>${esc(o)}</span></label>`}).join("")}</fieldset>`).join("")}</div><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="goalReviewSave">Salvar novos objetivos</button></div>`);byId("goalReviewSave").onclick=()=>{let answers=[],missing=false;document.querySelectorAll("[data-goal-question]").forEach(box=>{let selected=[...box.querySelectorAll("input:checked")].map(x=>Number(x.value));if(!selected.length)missing=true;answers.push(box.dataset.multi==="1"?selected:selected[0])});if(missing)return toast("Responda todas as perguntas antes de salvar.","warn","Faltam respostas");D.onboardingProfile={...(D.onboardingProfile||{}),answers,updatedAt:new Date().toISOString()};D.missions=D.missions.filter(m=>!(m.source==="smart-daily"&&!m.done));D.smartDaily={date:"",missionIds:[]};save();closeM();ensureSmartDaily();render();toast("As próximas missões usarão seus novos objetivos. Nenhum progresso foi apagado.","success","Objetivos atualizados")}}

function pagePlainHtml(p){let text=String(p?.content||"");return text?text.split(/\n{2,}/).map(x=>`<p>${esc(x).replace(/\n/g,"<br>")}</p>`).join(""):"<p><br></p>"}
function sanitizePageHtml(html=""){let doc=new DOMParser().parseFromString(`<div>${html}</div>`,"text/html"),allowed=new Set(["DIV","P","BR","H1","H2","H3","UL","OL","LI","B","STRONG","I","EM","U","S","BLOCKQUOTE","HR","LABEL","INPUT"]);doc.body.querySelectorAll("*").forEach(el=>{if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);return}[...el.attributes].forEach(a=>{let keep=el.tagName==="INPUT"&&["type","checked","disabled"].includes(a.name);if(!keep)el.removeAttribute(a.name)});if(el.tagName==="INPUT"){el.type="checkbox";el.disabled=false}});return doc.body.firstElementChild?.innerHTML||""}
function pageTemplate(kind){let d=new Intl.DateTimeFormat("pt-BR",{dateStyle:"long"}).format(new Date()),map={blank:["📄","Nova página","<p><br></p>"],daily:["📅",`Registro de ${d}`,"<h1>Registro diário</h1><h2>Prioridades</h2><ul><li>Minha prioridade principal</li></ul><h2>Notas</h2><p><br></p><h2>Fechamento do dia</h2><p>O que avançou? O que ajustar amanhã?</p>"],project:["🚀","Plano de projeto","<h1>Objetivo</h1><p>Descreva o resultado esperado.</p><h2>Próximas ações</h2><ul><li>Primeiro passo</li><li>Segundo passo</li></ul><h2>Referências</h2><p><br></p>"],week:["🗓️","Planejamento semanal","<h1>Planejamento da semana</h1><h2>Três prioridades</h2><ol><li>Prioridade 1</li><li>Prioridade 2</li><li>Prioridade 3</li></ol><h2>Não esquecer</h2><ul><li>Pendência</li></ul>"]};return map[kind]||map.blank}
function newPageModal(){modal(`<div class="mh"><div><h2>Criar página</h2><p class="sub">Comece em branco ou use uma estrutura pronta.</p></div><button class="x" id="cx">×</button></div><div class="pageTemplateGrid">${[["blank","📄","Em branco"],["daily","📅","Registro diário"],["project","🚀","Plano de projeto"],["week","🗓️","Planejamento semanal"]].map(x=>`<button data-page-template="${x[0]}"><span>${x[1]}</span><b>${x[2]}</b></button>`).join("")}</div>`);document.querySelectorAll("[data-page-template]").forEach(b=>b.onclick=()=>{let t=pageTemplate(b.dataset.pageTemplate),p={id:id(),icon:t[0],title:t[1],content:"",contentHtml:t[2],updatedAt:new Date().toISOString()};D.pages.push(p);D.activePage=p.id;save();closeM();nav="organize";render();setTimeout(()=>byId("pt")?.focus(),60)})}
function organizeV46(){let p=D.pages.find(x=>x.id===D.activePage)||D.pages[0];D.activePage=p?.id;let html=p?sanitizePageHtml(p.contentHtml||pagePlainHtml(p)):"";return header("Organização","Páginas, planos e registros em um espaço flexível",`<button class="btn" data-new-page>＋ Nova página</button>`)+`<div class="notion notionPro"><aside class="card pages notionSidebar"><div class="notionSideTitle"><b>Meu espaço</b><span>${D.pages.length} página(s)</span></div><input id="pageSearch" class="field" placeholder="Buscar página..."><div id="pageList">${D.pages.map(x=>`<button class="${x.id===p?.id?"on":""}" data-page="${x.id}" data-page-search="${esc(String(x.title||"").toLocaleLowerCase("pt-BR"))}"><span>${esc(x.icon||"📄")}</span><b>${esc(x.title||"Sem título")}</b></button>`).join("")}</div></aside><section class="card editor notionEditor">${p?`<div class="notionEditorTop"><input id="pageIcon" class="pageIconField" maxlength="2" value="${esc(p.icon||"📄")}" aria-label="Ícone da página"><div><input id="pt" class="notionTitle" maxlength="100" value="${esc(p.title||"")}"><small>Atualizada ${p.updatedAt?new Date(p.updatedAt).toLocaleString("pt-BR"):"agora"}</small></div></div><div class="notionToolbar" role="toolbar"><button data-editor-cmd="formatBlock" data-editor-value="h1">Título</button><button data-editor-cmd="formatBlock" data-editor-value="h2">Subtítulo</button><button data-editor-cmd="bold"><b>B</b></button><button data-editor-cmd="italic"><i>I</i></button><button data-editor-cmd="insertUnorderedList">• Lista</button><button data-editor-cmd="insertOrderedList">1. Lista</button><button data-editor-cmd="formatBlock" data-editor-value="blockquote">❝</button><button data-editor-check>☑ Tarefa</button><button data-editor-hr>—</button></div><div id="pe" class="notionContent" contenteditable="true" data-placeholder="Digite '/' para começar...">${html}</div><div class="notionEditorFoot"><span id="pageCount">${String(p.content||"").length} caracteres</span><div class="row"><button class="pill" data-duplicate-page="${p.id}">Duplicar</button><button class="btn" data-savepage="${p.id}">Salvar página</button><button class="iconAction danger" data-delpage="${p.id}" title="Excluir página">×</button></div></div>`:`<div class="notionEmpty"><span>📄</span><h2>Crie sua primeira página</h2><button class="btn" data-new-page>Escolher modelo</button></div>`}</section></div>`}
