function hrow(h){let current=Number(h.toolProgress?.[iso()]||0),goal=Number(h.toolGoal||0);return`<div class="habit" data-habit-card="${h.id}"><button class="check ${done(h)?"done":""}" data-h="${h.id}">✓</button><div class="grow habitOpenArea" data-open-habit="${h.id}" tabindex="0" role="button" title="Abrir este hábito no Planner"><div class="ht">${esc(h.title)}</div><div class="meta">${(h.bonus||[]).map(b=>`<span class="tag ${b.k==="hydration"?"blue":b.k==="focus"?"green":""}">${ATTR.find(a=>a[0]===b.k)?.[4]} +${b.n}</span>`).join("")}${goal?`<span class="habitLinkedProgress">${current}/${goal} ${esc(h.toolUnit||"")}</span>`:""}</div></div><div class="xp">ϟ ${h.xp}</div></div>`}
function completeMission(m,fromTool=false){if(!m||m.done)return false;m.done=true;m.completedAt=new Date().toISOString();m.earnedXP=addXP(m.xp,m.title,`mission:${m.id}`);hist("mission_done",{title:m.title,missionId:m.id,amount:m.earnedXP,completedAt:m.completedAt,fromTool});evaluateTitles(true);save();if(!fromTool)taskFx(m.title);return true}
function openMissionTarget(mid){if(!mid)return;focusMissionId=mid;missionTab="open";nav="missions";render();scrollTo(0,0);setTimeout(()=>{let el=document.querySelector(`[data-mission-card="${mid}"]`);if(el){el.scrollIntoView({behavior:"smooth",block:"center"});el.classList.add("focusTargetPulse");setTimeout(()=>el.classList.remove("focusTargetPulse"),2200)}},140)}
