  function filterFinanceRows(kind){let box=byId(kind==="expense"?"finExpenseRows":"finIncomeRows"),empty=byId(kind==="expense"?"finExpenseEmpty":"finIncomeEmpty"),q=(byId(kind==="expense"?"finExpenseSearch":"finIncomeSearch")?.value||"").trim().toLocaleLowerCase("pt-BR"),status=byId(kind==="expense"?"finExpenseStatus":"finIncomeStatus")?.value||"all",cat=byId(kind==="expense"?"finExpenseCategory":"finIncomeCategory")?.value||"all",visible=0;if(!box)return;box.querySelectorAll(".financeFilterRow").forEach(row=>{let current=String(row.dataset.finStatus||""),statusOk=status==="all"||(kind==="expense"&&status==="pending"?["pending","soon","overdue"].includes(current):current===status),ok=(!q||String(row.dataset.finSearch||"").includes(q))&&statusOk&&(cat==="all"||String(row.dataset.finCategory||"")===cat);row.classList.toggle("financeFilteredOut",!ok);row.setAttribute("aria-hidden",ok?"false":"true");if(ok)visible++});if(empty)empty.hidden=visible>0;let count=box.previousElementSibling?.querySelector?.(".financeCount");if(count)count.textContent=`${visible} lançamento(s)`}
