function mission(){modal(`<div class="mh"><h2>Nova Missão</h2><button class="x" id="cx">×</button></div><div class="form"><label>Título</label><input id="mt" class="field"><label>Descrição</label><textarea id="md" class="field"></textarea><label>Prazo</label><input id="mdu" class="field" type="date"><div class="profileEditGrid"><div><label>XP</label><input id="mx" class="field" type="number" value="100"></div><div><label>Tempo estimado (min)</label><input id="mmin" class="field" type="number" min="5" max="180" value="30"></div></div><button class="btn" id="ms" style="margin-top:12px">Criar</button></div>`);cx.onclick=closeM;ms.onclick=()=>{if(!mt.value.trim())return;D.missions.push({id:id(),title:mt.value.trim(),desc:md.value.trim(),due:mdu.value,xp:+mx.value||100,estimatedMinutes:Math.max(5,+mmin.value||30),done:false});evaluateTitles(true);save();closeM();render();toast("Missão criada com sucesso.","success","Missão salva")}}
function proto(days){let labels={7:"Adaptação",21:"Consolidação",30:"Consistência",90:"Transformação"};modal(`<div class="mh"><div><div class="kicker">PROTOCOLO ${days} DIAS</div><h2>${labels[days]||"Protocolo pessoal"}</h2></div><button class="x" id="cx">×</button></div><div class="protocolIntro"><b>Como funciona</b><p>Cria uma missão principal com prazo e um hábito diário ligado ao objetivo. Você acompanha o progresso no Planner.</p></div><div class="form"><label>Objetivo</label><input id="prt" class="field" placeholder="Ex.: Voltar a estudar inglês"><label>Ação diária</label><input id="pra" class="field" placeholder="Ex.: Estudar inglês por 20 minutos"><div class="modalActions"><button class="pill" id="prCancel">Cancelar</button><button class="btn" id="prs">Criar protocolo</button></div></div>`);cx.onclick=closeM;prCancel.onclick=closeM;prs.onclick=()=>{let goal=prt.value.trim(),daily=pra.value.trim();if(!goal)return toast("Informe o objetivo principal.","warn");if(!daily)daily=`Avançar em: ${goal}`;let due=new Date();due.setDate(due.getDate()+days);D.missions.push({id:id(),title:`Protocolo ${days}d — ${goal}`,desc:`${labels[days]||"Protocolo"}: ${daily}`,due:iso(due),xp:Math.min(500,Math.max(100,days*8)),done:false,protocol:days});D.habits.push({id:id(),title:daily,desc:`Etapa diária do protocolo de ${days} dias: ${goal}`,xp:50,bonus:[{k:"discipline",n:1}],rest:[],log:{},xpLog:{},protocol:days});evaluateTitles(true);save();closeM();render();toast(`Protocolo de ${days} dias criado com missão e hábito diário.`,"success","Protocolo ativado")}}
function titles(){let metrics=titleMetrics();modal(`<div class="mh"><div><h2>130 Títulos</h2><p class="sub">${D.titles.filter(t=>t.unlocked).length} conquistados • novos títulos são equipados automaticamente</p></div><button class="x" id="cx">×</button></div><div class="titleLegend"><span>🏆 Conquistado</span><span>🔒 Meta ainda não atingida</span><span>⚡ Autoequipar ao desbloquear</span></div><div class="grid2 titleGrid">${D.titles.map(t=>{let rule=titleRule(t.name,metrics);return`<div class="card titleCard ${t.unlocked?"unlocked":"locked"} ${t.equipped?"equipped":""}"><div class="titleCardHead"><b>${t.unlocked?"🏆":"🔒"} ${esc(t.name)}</b>${t.equipped?`<span class="titleEquipped">EQUIPADO</span>`:""}</div><p class="sub titleRule">${esc(rule.desc)}</p>${t.unlocked&&!t.equipped?`<button class="pill" data-tt="${t.id}">Equipar manualmente</button>`:t.equipped?`<span class="titleAuto">⚡ Título ativo</span>`:`<span class="titlePending">Continue evoluindo</span>`}</div>`}).join("")}</div>`);let c=byId("cx");if(c)c.onclick=closeM;document.querySelectorAll("[data-tt]").forEach(b=>b.onclick=()=>{D.titles.forEach(t=>t.equipped=t.id===b.dataset.tt);save();closeM();titles();toast("Título equipado no seu perfil.","success","Título alterado")})}
function drawRadar(){let c=document.querySelector("#radar");if(!c)return;let r=c.getBoundingClientRect(),d=devicePixelRatio||1;c.width=r.width*d;c.height=r.height*d;let x=c.getContext("2d");x.scale(d,d);let cx=r.width/2,cy=r.height/2,R=Math.min(r.width,r.height)*.34,N=ATTR.length,max=Math.max(20,...ATTR.map(a=>D.attrs[a[0]]||0));for(let z=1;z<=5;z++){x.beginPath();ATTR.forEach((a,i)=>{let g=-Math.PI/2+i*2*Math.PI/N,rr=R*z/5,px=cx+Math.cos(g)*rr,py=cy+Math.sin(g)*rr;i?x.lineTo(px,py):x.moveTo(px,py)});x.closePath();x.strokeStyle="#202823";x.stroke()}ATTR.forEach((a,i)=>{let g=-Math.PI/2+i*2*Math.PI/N;x.fillStyle="#dce5df";x.font="11px sans-serif";let px=cx+Math.cos(g)*(R+32),py=cy+Math.sin(g)*(R+22);x.textAlign=px<cx-10?"right":px>cx+10?"left":"center";x.fillText(a[1],px,py)});x.beginPath();ATTR.forEach((a,i)=>{let g=-Math.PI/2+i*2*Math.PI/N,rr=R*((D.attrs[a[0]]||0)/max),px=cx+Math.cos(g)*rr,py=cy+Math.sin(g)*rr;i?x.lineTo(px,py):x.moveTo(px,py)});x.closePath();x.fillStyle="#23da6744";x.strokeStyle="#35ef79";x.lineWidth=2;x.fill();x.stroke()}
async function photoData(file){return new Promise((resolve,reject)=>{if(!file)return resolve("");if(!file.type.startsWith("image/"))return reject(new Error("Escolha uma imagem válida."));if(file.size>8*1024*1024)return reject(new Error("A imagem deve ter no máximo 8 MB."));let fr=new FileReader();fr.onerror=()=>reject(new Error("Não foi possível ler a imagem."));fr.onload=()=>{let img=new Image();img.onerror=()=>reject(new Error("Imagem inválida."));img.onload=()=>{let size=320,c=document.createElement("canvas"),ctx=c.getContext("2d"),scale=Math.min(1,size/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale));c.width=w;c.height=h;ctx.drawImage(img,0,0,w,h);resolve(c.toDataURL("image/jpeg",.86))};img.src=fr.result};fr.readAsDataURL(file)})}
function editProfileModal(){let pendingPhoto=D.profile.photo||"";modal(`<div class="mh"><div><h2>Editar perfil</h2><p class="sub">Personalize sua identidade no Smart Life.</p></div><button class="x" id="cx">×</button></div><div class="profileEditor"><div class="photoEditor"><div class="avatar profilePreview" id="profilePreview">${pendingPhoto?`<img class="profilePhoto" src="${pendingPhoto}">`:esc((D.profile.avatar||"SL").slice(0,3))}</div><div><label class="fileBtn" for="profilePhotoInput">▣ Escolher foto</label><input id="profilePhotoInput" type="file" accept="image/*" hidden><button class="linkBtn" id="removePhoto" type="button">Remover foto</button><p class="sub">A foto é reduzida e salva no próprio backup.</p></div></div><div class="profileEditGrid form"><div><label>Nome exibido</label><input id="epName" class="field" maxlength="60" value="${esc(D.profile.name)}"></div><div><label>Nome de usuário</label><input id="epUser" class="field" maxlength="32" value="${esc(D.profile.username)}"></div></div><div class="form"><label>Iniciais (usadas quando não houver foto)</label><input id="epAvatar" class="field" maxlength="3" value="${esc(D.profile.avatar||"SL")}"></div><div class="modalActions"><button class="pill" id="epBack">← Voltar</button><button class="btn" id="epSave">Salvar perfil</button></div></div>`);cx.onclick=closeM;epBack.onclick=closeM;removePhoto.onclick=()=>{pendingPhoto="";profilePreview.innerHTML=esc((epAvatar.value||"SL").slice(0,3).toUpperCase());toast("A foto será removida ao salvar.","info")};profilePhotoInput.onchange=async()=>{try{pendingPhoto=await photoData(profilePhotoInput.files?.[0]);profilePreview.innerHTML=`<img class="profilePhoto" src="${pendingPhoto}">`;toast("Foto pronta para salvar.","info","Foto selecionada")}catch(e){toast(e.message||"Não foi possível carregar a foto.","error")}};epAvatar.oninput=()=>{if(!pendingPhoto)profilePreview.textContent=(epAvatar.value||"SL").slice(0,3).toUpperCase()};epSave.onclick=()=>{let nextName=epName.value.trim(),nextUser=epUser.value.trim();if(nextName.length<2)return toast("Informe um nome de exibição válido.","error","Perfil não alterado");let updated=window.SmartLifeAuth?.updateCurrentAccount?.({accountId:currentAccount?.id||"",displayName:nextName,username:nextUser,email:currentAccount?.email||""});if(!updated?.ok)return toast(updated?.message||"Não foi possível atualizar a conta.","error","Perfil não alterado");currentAccount=updated.account;window.__smartLifeAccount=updated.account;D.profile.name=updated.account.displayName;D.profile.username=updated.account.username;D.profile.avatar=(epAvatar.value.trim()||"SL").slice(0,3).toUpperCase();D.profile.photo=pendingPhoto;save();closeM();render();toast("As alterações foram salvas nesta conta e continuarão após reabrir o aplicativo.","success","Perfil atualizado")}}
